    bv_unsigned sp mod 16 = 0 -> aceil <= lo -> lo <= bv_unsigned sp - ASTREAM_CTOR_STACK -> bv_unsigned sp <= 0x7fffffffffff -> bv_unsigned sp + 64 <= shi ->
    bv_unsigned sp <= B -> 0 <= N < 2^26 -> Z.of_nat (length ds) = N -> 0 <= D < 2^64 ->
    cobj LB LF (bv_unsigned sp) shi bs SZ_BS -> bs mod 8 = 0 ->
